const visual = {
  prepare: function (input) {
    return [
      { kind: 'text', payload: '一元二次方程求根公式' },
      { kind: 'text', payload: '3x²' },
      { kind: 'text', payload: ' − ' },
      { kind: 'text', payload: '−5x' },
      { kind: 'text', payload: '−2' },
      { kind: 'text', payload: ' = 0' },
      { kind: 'text', payload: 'x =' },
      { kind: 'text', payload: '−b ± √(b² − 4ac)' },
      { kind: 'text', payload: '2a' },
      { kind: 'text', payload: 'a = 3' },
      { kind: 'text', payload: 'b = −5' },
      { kind: 'text', payload: 'c = −2' },
      { kind: 'text', payload: '判别式' },
      { kind: 'text', payload: 'Δ = b² − 4ac = 49' }
    ];
  },
  render: function (input, metrics) {
    var W = (input.viewport && input.viewport.widthDu) || 800;
    var H = (input.viewport && input.viewport.heightDu) || 600;
    var paths = [];
    var children = [];
    var dark = '#1f2937';
    var blue = '#2563eb';
    var orange = '#ea580c';
    var green = '#16a34a';
    var purple = '#7c3aed';
    var font = 'ui-monospace, SFMono-Regular, Menlo, Consolas, monospace';

    function addPath(id, commands, style) {
      paths.push({ id: id, commands: commands });
      var node = { type: 'path', pathId: id };
      if (style) {
        for (var key in style) {
          if (Object.prototype.hasOwnProperty.call(style, key)) node[key] = style[key];
        }
      }
      children.push(node);
    }
    function addLabel(text, x, y, size, fill, anchor, weight) {
      children.push({
        type: 'label',
        x: x,
        y: y,
        text: text,
        fontSize: size,
        fill: fill,
        fontFamily: font,
        anchor: anchor || 'start',
        textAnchor: anchor || 'start',
        fontWeight: weight || 'normal'
      });
    }
    function rectCmd(x, y, w, h) {
      return visualSdk.polyline([[x, y], [x + w, y], [x + w, y + h], [x, y + h], [x, y]]);
    }
    function lineCmd(x1, y1, x2, y2) {
      return visualSdk.polyline([[x1, y1], [x2, y2]]);
    }
    function chip(label, x, y, color, idBase) {
      var fs = 20;
      var cwChip = fs * 0.6;
      var w = label.length * cwChip + 24;
      var h = 36;
      addPath(idBase + 'ChipBox', rectCmd(x, y, w, h), { fill: '#ffffff', stroke: color, strokeWidth: 2 });
      addLabel(label, x + w / 2, y + h / 2 + 7, fs, color, 'middle', 'bold');
      return { x: x, y: y, w: w, h: h, cy: y + h / 2 };
    }

    addPath('bg', rectCmd(0, 0, W, H), { fill: '#ffffff', stroke: 'none' });
    addLabel('一元二次方程求根公式', W / 2, 44, 24, dark, 'middle', 'bold');

    var eqFont = 24;
    var eqCw = eqFont * 0.6;
    var eqTokens = [
      { t: '3x²', c: blue },
      { t: ' − ', c: dark },
      { t: '−5x', c: orange },
      { t: ' − ', c: dark },
      { t: '−2', c: green },
      { t: ' = 0', c: dark }
    ];
    var eqLen = 0;
    var i;
    for (i = 0; i < eqTokens.length; i++) eqLen += eqTokens[i].t.length;
    var eqX = (W - eqLen * eqCw) / 2;
    var eqY = 92;
    var eqCursor = eqX;
    for (i = 0; i < eqTokens.length; i++) {
      addLabel(eqTokens[i].t, eqCursor, eqY, eqFont, eqTokens[i].c, 'start');
      eqCursor += eqTokens[i].t.length * eqCw;
    }

    var fFont = 30;
    var cw = fFont * 0.6;
    var numText = '−b ± √(b² − 4ac)';
    var numLen = numText.length;
    var numW = numLen * cw;
    var x0 = (W - numW) / 2 + 20;
    var formulaY = 200;
    var barY = 232;
    var denomY = 272;
    var denomX = x0 + (numW - 2 * cw) / 2;

    var discStart = x0 + 7 * cw;
    var discEnd = x0 + 15 * cw;
    addPath('discHighlight', rectCmd(discStart - 4, formulaY - 30, (discEnd - discStart) + 8, 42), { fill: '#f5f3ff', stroke: purple, strokeWidth: 1.5 });

    addLabel('x =', x0 - 78, barY + 10, 30, dark, 'start', 'bold');
    addLabel(numText, x0, formulaY, fFont, dark, 'start');
    addLabel('2a', denomX, denomY, fFont, dark, 'start');
    addPath('fracBar', lineCmd(x0, barY, x0 + numW, barY), { stroke: dark, strokeWidth: 2.5, fill: 'none' });

    var ulY = formulaY + 12;
    addPath('ulB1', lineCmd(x0 + 1 * cw, ulY, x0 + 2 * cw, ulY), { stroke: orange, strokeWidth: 5, strokeLinecap: 'round', fill: 'none' });
    addPath('ulB2', lineCmd(x0 + 7 * cw, ulY, x0 + 8 * cw, ulY), { stroke: orange, strokeWidth: 5, strokeLinecap: 'round', fill: 'none' });
    addPath('ulA1', lineCmd(x0 + 13 * cw, ulY, x0 + 14 * cw, ulY), { stroke: blue, strokeWidth: 5, strokeLinecap: 'round', fill: 'none' });
    addPath('ulC1', lineCmd(x0 + 14 * cw, ulY, x0 + 15 * cw, ulY), { stroke: green, strokeWidth: 5, strokeLinecap: 'round', fill: 'none' });
    var ulDenY = denomY + 12;
    addPath('ulADen', lineCmd(denomX + 1 * cw, ulDenY, denomX + 2 * cw, ulDenY), { stroke: blue, strokeWidth: 5, strokeLinecap: 'round', fill: 'none' });

    var bTargetX = x0 + 1 * cw + cw / 2;
    var bTargetY = ulY;
    var aTargetX = denomX + 1 * cw + cw / 2;
    var aTargetY = ulDenY;
    var cTargetX = x0 + 14 * cw + cw / 2;
    var cTargetY = ulY;

    var bChipX = 60;
    var bChipY = 120;
    var bChipW = ('b = −5').length * 12 + 24;
    var cChipX = W - 220;
    var cChipY = 120;
    var aChipX = 60;
    var aChipY = 330;
    var aChipW = ('a = 3').length * 12 + 24;
    var bElbowX = Math.max(bChipX + bChipW + 20, bTargetX - 60);
    var aElbowX = Math.max(aChipX + aChipW + 20, aTargetX - 40);
    var cElbowX = cChipX - 20;

    addPath('leaderB', visualSdk.polyline([[bChipX + bChipW, bChipY + 18], [bElbowX, bChipY + 18], [bElbowX, bTargetY], [bTargetX, bTargetY]]), { stroke: orange, strokeWidth: 1.8, fill: 'none' });
    addPath('dotB', visualSdk.circle(bTargetX, bTargetY, 4), { fill: orange, stroke: 'none' });

    addPath('leaderC', visualSdk.polyline([[cChipX, cChipY + 18], [cElbowX, cChipY + 18], [cElbowX, cTargetY], [cTargetX, cTargetY]]), { stroke: green, strokeWidth: 1.8, fill: 'none' });
    addPath('dotC', visualSdk.circle(cTargetX, cTargetY, 4), { fill: green, stroke: 'none' });

    addPath('leaderA', visualSdk.polyline([[aChipX + aChipW, aChipY + 18], [aElbowX, aChipY + 18], [aElbowX, aTargetY], [aTargetX, aTargetY]]), { stroke: blue, strokeWidth: 1.8, fill: 'none' });
    addPath('dotA', visualSdk.circle(aTargetX, aTargetY, 4), { fill: blue, stroke: 'none' });

    chip('b = −5', bChipX, bChipY, orange, 'b');
    chip('c = −2', cChipX, cChipY, green, 'c');
    chip('a = 3', aChipX, aChipY, blue, 'a');

    var boxW = 230;
    var boxH = 78;
    var boxX = W - boxW - 30;
    var boxY = H - boxH - 30;
    addPath('deltaBox', rectCmd(boxX, boxY, boxW, boxH), { fill: '#f5f3ff', stroke: purple, strokeWidth: 2.5 });
    addLabel('判别式', boxX + boxW / 2, boxY + 26, 15, purple, 'middle', 'bold');
    addLabel('Δ = b² − 4ac = 49', boxX + boxW / 2, boxY + 55, 19, purple, 'middle', 'bold');

    return {
      schemaVersion: 1,
      sceneId: 'quadratic-formula',
      revision: input.revision,
      viewBox: { x: 0, y: 0, width: W, height: H },
      paths: paths,
      root: { type: 'group', children: children }
    };
  }
};
